@import "tailwindcss";
@theme {
  --color-brand-500: oklch(0.6 0.2 250);
  --font-display: "Inter", sans-serif;
  --breakpoint-3xl: 120rem;
  --spacing: 0.3rem;
  --tab-size-github: 8;
}
@theme inline {
  --color-accent: var(--color-brand-500);
}
@custom-variant hocus (&:hover, &:focus);
@custom-variant theme-dark {
  &:where([data-theme=dark] *) {
    @slot;
  }
}
@utility content-auto {
  content-visibility: auto;
}
@utility tab-* {
  tab-size: --value(--tab-size-*, integer, [integer]);
}
@layer components {
  .btn {
    @apply rounded-lg px-4 py-2 font-semibold hover:bg-brand-500/80;
  }
}
.card {
  padding: --spacing(4);
  color: --alpha(var(--color-brand-500) / 50%);
  background: --theme(--color-red-500);
  @variant dark {
    color: white;
  }
}
@source inline("{hover:,}bg-red-{100..300..100}");
@source not inline("bg-red-200");

